#include "resident_scenes.h"
#include <iostream>
#include <limits>
using namespace mc;
struct Hit {float t=1e9f;Vec3 a,b,c,color;float material=0;int x=0,z=0;bool dynamic=false;};
void cast(const Mesh& mesh,Vec3 o,Vec3 d,Hit& hit,int x,int z,bool dynamic){for(size_t i=0;i+2<mesh.indices.size();i+=3){const auto& va=mesh.vertices[mesh.indices[i]];Vec3 a=va.position,b=mesh.vertices[mesh.indices[i+1]].position,c=mesh.vertices[mesh.indices[i+2]].position,e1=b-a,e2=c-a,n=cross(d,e2);float det=dot(e1,n);if(std::abs(det)<1e-7f)continue;Vec3 off=o-a;float u=dot(off,n)/det;if(u<0||u>1)continue;Vec3 q=cross(off,e1);float v=dot(d,q)/det;if(v<0||u+v>1)continue;float t=dot(e2,q)/det;if(t>.001f&&t<hit.t)hit={t,a,b,c,va.color,va.material,x,z,dynamic};}}
void vec(Vec3 p){std::cout<<p.x<<','<<p.y<<','<<p.z;}
int main(){for(const char* scene:{"residents-talk","residents-startle"}){Game game;game.initialize();ResidentCapture capture;std::string error;if(!capture.prepare(game,scene,std::cout,error,[]{return true;}))return 1;std::cout<<"eye=";vec(capture.eye);std::cout<<" target=";vec(capture.target);std::cout<<" player=";vec(game.player);std::cout<<'\n';Vec3 fw=normalized(capture.target-capture.eye),r=normalized(cross({0,1,0},fw)),up=cross(fw,r);auto dynamic=game.dynamicMesh();for(Vec2 pixel: {Vec2{270,440},Vec2{270,350},Vec2{280,520},Vec2{20,300},Vec2{480,270}}){float sx=((pixel.x+.5f)/960*2-1)*std::tan(68*Pi/360)*960/541,sy=(1-(pixel.y+.5f)/541*2)*std::tan(68*Pi/360);Vec3 d=normalized(fw+r*sx+up*sy);Hit h;for(const auto& chunk:game.world.chunks)cast(chunk.mesh,capture.eye,d,h,chunk.x,chunk.z,false);cast(dynamic,capture.eye,d,h,0,0,true);std::cout<<"pixel="<<pixel.x<<','<<pixel.y<<" t="<<h.t<<" dynamic="<<h.dynamic<<" chunk="<<h.x<<','<<h.z<<" material="<<h.material<<" color=";vec(h.color);std::cout<<" vertices=";vec(h.a);std::cout<<" / ";vec(h.b);std::cout<<" / ";vec(h.c);std::cout<<'\n';}}}
